const searches = [];

const config = [
  {
    region: "USA",
    cities: [
      "New York, NY",
      "Los Angeles, CA",
      "Miami, FL",
      "Houston, TX",
      "Dallas, TX",
      "Austin, TX",
      "Phoenix, AZ",
      "Chicago, IL",
      "Atlanta, GA",
      "Tampa, FL",
      "Orlando, FL",
      "Charlotte, NC",
      "Raleigh, NC",
      "Nashville, TN",
      "Denver, CO",
      "Las Vegas, NV",
      "San Diego, CA",
      "San Francisco, CA",
      "San Jose, CA",
      "Seattle, WA",
      "Boston, MA",
      "Washington, DC",
      "Philadelphia, PA",
      "Scottsdale, AZ",
      "Fort Lauderdale, FL"
    ]
  }
];

const niches = [
  "dental clinic",
  "cosmetic dentist",
  "orthodontist",
  "med spa",
  "aesthetic clinic",
  "plastic surgery clinic",
  "dermatology clinic",
  "fertility clinic",
  "chiropractic clinic",
  "optometry clinic",
  "hair transplant clinic",
  "weight loss clinic"
];

for (const region of config) {
  for (const city of region.cities) {
    for (const niche of niches) {
      searches.push({
        json: {
          region: region.region,
          city: city,
          niche: niche,
          query: `${niche} in ${city}`
        }
      });
    }
  }
}

return searches;

const inputItems = $input.all();

return inputItems.map(item => {
  const d = item.json;

  // Helper: safely get the first value from an array
  const first = (value) => {
    if (Array.isArray(value) && value.length > 0) {
      return value[0];
    }
    return null;
  };

  // Helper: extract URL from enriched profile objects
  const profileUrl = (profiles) => {
    if (!Array.isArray(profiles) || profiles.length === 0) {
      return null;
    }

    return profiles[0]?.externalProfileURL || null;
  };

  // Extract social URLs
  const facebook =
    first(d.facebooks) ||
    profileUrl(d.facebookProfiles);

  const instagram =
    first(d.instagrams) ||
    profileUrl(d.instagramProfiles);

  const linkedin =
    first(d.linkedIns) ||
    first(d.linkedin) ||
    first(d.linkedins);

  // Extract email if Apify found one
  const email = first(d.emails);

  // Extract domain
  let domain = d.domain || null;

  if (!domain && d.website) {
    try {
      domain = new URL(d.website).hostname
        .replace(/^www\./, '');
    } catch (error) {
      domain = null;
    }
  }

  return {
    json: {
      company_name: d.title || null,
      category: d.categoryName || null,

      website: d.website || null,
      domain: domain,

      phone: d.phone || null,
      phone_unformatted: d.phoneUnformatted || null,

      address: d.address || null,
      street: d.street || null,
      city: d.city || null,
      state: d.state || null,
      postal_code: d.postalCode || null,
      country: d.countryCode || null,

      google_maps_url: d.url || null,

      rating: d.totalScore || null,
      review_count: d.reviewsCount || null,

      facebook: facebook,
      instagram: instagram,
      linkedin: linkedin,

      email: email,
      email_source: email ? "Apify" : null,
      email_verified: false,

      description: d.description || null,

      permanently_closed: d.permanentlyClosed || false,
      temporarily_closed: d.temporarilyClosed || false,

      // Keep the original search context
      search_niche: $('Loop Over Items').item.json.niche || null,
      search_city: $('Loop Over Items').item.json.city || null,
      search_region: $('Loop Over Items').item.json.region || null
    }
  };
});

// 1. Extract all items in batch mode
const allItems = $input.all();

// 2. Filter out sentry, wixpress, and placeholder noise
const cleanItems = allItems.filter(item => {
  const email = (item.json.email || '').toLowerCase();

  const isNoise = email.includes('sentry') || 
                  email.includes('wixpress') || 
                  email.includes('example.com') ||
                  email.includes('sentry-next') ||
                  email.endsWith('.png') || 
                  email.endsWith('.jpg');

  return email && !isNoise;
});

// 3. Find target priority email prefixes (info@, dental@, contact@, dds@)
const priorityList = cleanItems.filter(item => {
  const e = item.json.email.toLowerCase();
  return e.startsWith('info@') || e.startsWith('dental@') || e.startsWith('contact@') || e.startsWith('dds@');
});

// 4. Return priority list, or fallback to first valid clean item, or empty array
if (priorityList.length > 0) {
  return priorityList.slice(0, 1); // Keep the single best primary inbox
} else if (cleanItems.length > 0) {
  return [cleanItems[0]];
} else {
  return [];
}

// 1. Get the original full lead data (contains socials, address, phone, etc.)
const allOriginalLeads = $('Normalize Lead Data').all().map(item => item.json);

// 2. Get the clean email extracted by the filter node
const filteredItems = $input.all();

const getDomain = (url) => {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    return url || '';
  }
};

return filteredItems.map(item => {
  const currentItem = item.json;
  const extractedEmail = currentItem.email || null;
  const extractedUrl = currentItem.url || currentItem.sourceUrl || '';
  const currentDomain = getDomain(extractedUrl);

  // Match back to the original lead record by domain
  const matchedLead = allOriginalLeads.find(lead => {
    if (!lead.website && !lead.domain) return false;
    const leadDomain = getDomain(lead.website || lead.domain || '');
    return leadDomain === currentDomain;
  }) || allOriginalLeads[0] || {};

  // Combine original lead details + newly enriched email
  return {
    json: {
      ...matchedLead,
      website: extractedUrl || matchedLead.website || null,
      email: extractedEmail,
      email_source: 'Apify'
    }
  };
});

