// 1. Extract and clean raw JSON text from OpenAI output
const rawText = $input.item.json.output[0].content[0].text;
const cleanJsonString = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// 2. Parse raw string into structured evidence flags
const flags = JSON.parse(cleanJsonString);

// 3. Initialize scoring engine
let score = 0;
const reasons = [];

// ICP Signals
if (flags.icp_signals?.is_healthcare) { score += 10; reasons.push("Healthcare practice"); }
if (flags.icp_signals?.is_private_practice) { score += 15; reasons.push("Private practice"); }
if (flags.icp_signals?.is_approved_market) { score += 15; reasons.push("Approved target market"); }
if (flags.icp_signals?.specialty_tier >= 1) { score += 15; reasons.push("High specialty tier"); }

// Phone Dependency & Booking Friction
if (flags.phone_dependency?.call_to_book_prominent || flags.phone_dependency?.phone_number_in_header) {
  score += 15;
  reasons.push("Phone-dependent booking process");
}
if (flags.booking_friction?.directs_call_for_info || !flags.booking_friction?.has_direct_online_booking) {
  score += 10;
  reasons.push("Direct/online booking friction");
}

// Operational Pain & Patient Acquisition
if (flags.after_hours?.has_extended_hours) { score += 5; reasons.push("Has extended/after-hours service"); }
if (flags.patient_acquisition?.active_ad_campaigns) { score += 10; reasons.push("Active patient acquisition ads"); }
if (flags.patient_acquisition?.social_media_promotions_active) { score += 5; reasons.push("Active social media evidence"); }

// Determine Lead Temperature
let temperature = "COLD";
let status = "unqualified";

if (score >= 70) {
  temperature = "HOT";
  status = "qualified";
} else if (score >= 45) {
  temperature = "WARM";
  status = "qualified";
}

// 4. Output unified payload
return {
  json: {
    ...flags,
    qualification_score: score,
    lead_temperature: temperature,
    qualification_status: status,
    qualification_reasons: reasons
  }
};

const currentData = $input.item.json;
const origLead = $('Merge Enriched Lead Data').first().json || {};

const reasonsText = Array.isArray(currentData.qualification_reasons) 
  ? currentData.qualification_reasons.join(', ') 
  : (currentData.qualification_reasons || '');

return {
