    phone: origLead.phone_unformatted || origLead.phone || undefined,
    website: origLead.website || undefined,
    address1: origLead.street || origLead.address || undefined,
    city: origLead.city || undefined,
    state: origLead.state || undefined,
    postalCode: origLead.postal_code || undefined,
    country: origLead.country || 'US',
    source: origLead.source || 'n8n Scraper',

    // Map your custom fields using their exact IDs from your list
    customFields: [
      { id: "z0vqg5jlo3V4Ofp***", value: reasonsText }, // Example: Conversion Leak
      { id: "SuAL6bdvSQ1tSa***", value: String(origLead.rating || 0) },
      { id: "Zr2x8Lqjpxcm8A******", value: String(origLead.review_count || 0) },
      { id: "N3LJ2d1q3dDuF*****", value: String(currentData.qualification_score || 0) },
      { id: "Lhj4s3P3E****", value: origLead.google_maps_url || '' },
      { id: "pPVB0S8iElZS****", value: origLead.lead_id || origLead.domain || '' }
    ]
  }
};

